/* Browser-local runoff experiments, map inspection and field notes. */
(() => {
 'use strict';
 const key='zhishui-water-journey-v3';
 const covers={hard:{name:'硬化地面',coefficient:.9},mixed:{name:'混合地面',coefficient:.6},green:{name:'较多绿地',coefficient:.3}};
 const tabs=[[2,'径流实验'],[1,'河湖地图'],[3,'观察记录']];
 const featureNames={reflection:'水面反光',vegetation:'岸边植被',bank:'人工岸线',structure:'船只或桥梁'};
 const photoIds=['yangtze','qinhuai','xuanwu'];
 const fresh=()=>({step:2,found:false,chosen:0,rain:60,capacity:6,area:1,duration:60,trials:[],runs:[],recorded:false,photo:'xuanwu',note:'',notes:{},checks:{}});
 let state=fresh(),storageAvailable=true,controller=null,mapController=null,saveTimer;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=(v,min,max,fallback)=>Number.isFinite(+v)?Math.min(max,Math.max(min,+v)):fallback;
 const fmt=(v,digits=0)=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:digits});
 const input=v=>({rain:number(v.rain,0,120,60),capacity:number(v.capacity,0,25,6),area:number(v.area,.1,5,1),duration:number(v.duration,15,120,60)});
 function simulate(value={}){value=value&&typeof value==='object'?value:{};const p=input(value),cover=Object.hasOwn(covers,value.cover)?value.cover:'hard',coefficient=covers[cover].coefficient,seconds=p.duration*60,runoff=p.rain*coefficient*p.area/3.6,drained=Math.min(runoff,p.capacity),total=p.rain*p.area*1000*p.duration/60;return {...p,cover,coefficient,runoff,drained,stored:Math.max(0,runoff-drained)*seconds,total,absorbed:total*(1-coefficient),drainedVolume:drained*seconds,runoffVolume:runoff*seconds}}
 function comparison(trials=state.trials){for(let i=trials.length-1;i>=0;i--)for(let j=i-1;j>=0;j--){const a=simulate(trials[j]),b=simulate(trials[i]);if(a.rain===b.rain&&a.capacity===b.capacity&&a.area===b.area&&a.duration===b.duration&&a.cover!==b.cover)return [a,b]}return null}
 function restore(){try{const read=k=>{const raw=localStorage.getItem(k);if(!raw)return null;try{return JSON.parse(raw)}catch{return null}};const saved=read(key);let previous=saved?.version===3?saved.state:null;if(!previous){const old=read('zhishui-water-journey-v2');previous=old?.version===2?old.state:null}if(!previous)previous=read('zhishui-water-journey-v1')?.state;if(!previous)return;state={...fresh(),...previous,...input(previous)};state.step=[1,2,3].includes(previous.step)?previous.step:2;state.chosen=Math.round(number(previous.chosen,0,7,0));state.found=previous.found===true;state.recorded=previous.recorded===true;state.photo=photoIds.includes(previous.photo)?previous.photo:'xuanwu';state.notes=Object.fromEntries(photoIds.map(id=>[id,String(previous.notes?.[id]||'').slice(0,600)]));state.note=String(previous.note||state.notes[state.photo]||'').slice(0,600);state.notes[state.photo]=state.note;state.checks=Object.fromEntries(photoIds.map(id=>[id,Array.isArray(previous.checks?.[id])?previous.checks[id].filter(v=>Object.hasOwn(featureNames,v)):[]]));state.trials=Array.isArray(previous.trials)?previous.trials.filter(t=>t&&Object.hasOwn(covers,t.cover)&&Number.isFinite(t.rain)&&Number.isFinite(t.capacity)).slice(-6).map(t=>({...input(t),cover:t.cover})):[];state.runs=Array.isArray(previous.runs)?previous.runs.filter(r=>r&&Number.isFinite(r.rain)&&Number.isFinite(r.capacity)).slice(-6).map((r,i)=>({...input(r),id:i+1})):[]}catch{storageAvailable=false;state=fresh()}}
 function save(){try{localStorage.setItem(key,JSON.stringify({version:3,state}))}catch{storageAvailable=false}}
 const photo=()=>window.HydroAtlas.photos.find(p=>p.id===state.photo)||window.HydroAtlas.photos[0];
 const values=()=>Object.keys(covers).map(cover=>simulate({...state,cover}));
 function render(){return `<section id="journey" class="journey hydrology-lab"><header class="lab-heading"><div><h1>水文体验</h1><p>调整降雨和排水参数，比较三种地面的模拟径流与暂存水量。</p></div><button class="btn" data-export>导出记录</button></header><div id="journey-tabs" class="lab-tabs" role="tablist" aria-label="水文体验内容">${tabs.map(([id,label])=>`<button id="journey-tab-${id}" type="button" role="tab" data-step="${id}" aria-selected="${state.step===id}" aria-controls="journey-stage" tabindex="${state.step===id?0:-1}">${label}</button>`).join('')}</div><div id="journey-stage" class="journey-stage" role="tabpanel" aria-labelledby="journey-tab-${state.step}">${state.step===1?mapStage():state.step===2?experimentStage():observationStage()}</div>${storageAvailable?'':'<p class="lab-storage-notice">当前浏览器无法保存，离开后参数不会保留。</p>'}</section>`}
 function slider(name,label,min,max,step,unit){return `<label class="lab-control" for="journey-${name}"><span>${label}<span><output id="lab-${name}-output">${fmt(state[name],name==='area'?1:0)}</output> ${unit}</span></span><input id="journey-${name}" data-lab-param="${name}" type="range" min="${min}" max="${max}" step="${step}" value="${state[name]}" aria-label="${label}"></label>`}
 function experimentStage(){return `<div class="lab-workspace"><section class="lab-controls panel" aria-labelledby="lab-params-title"><h2 id="lab-params-title">实验参数</h2>${slider('rain','降雨强度',0,120,10,'mm/h')}<div class="lab-rain-presets" role="group" aria-label="雨强预设">${[20,60,100].map(v=>`<button id="lab-rain-${v}" data-lab-rain="${v}" aria-pressed="${state.rain===v}">${v} mm/h</button>`).join('')}</div>${slider('duration','降雨历时',15,120,15,'分钟')}${slider('area','汇水面积',.1,5,.1,'km²')}${slider('capacity','排水能力',0,25,1,'m³/s')}<button id="lab-save-run" class="btn primary" data-save-run>保存本组参数</button><button id="lab-reset-params" class="btn text" data-reset-params>恢复默认参数</button></section><section id="experiment-results" class="lab-results" aria-label="三种地面计算结果">${resultsHTML()}</section></div><section class="lab-run-panel panel"><div class="lab-run-heading"><h2>参数记录</h2><span>已保存 ${state.runs.length} / 6 组</span></div><div id="lab-run-records">${runsHTML()}</div></section><details class="model-details lab-model"><summary>计算方法与适用范围</summary><p>这是固定雨强的简化教学模型。地表产流量 Q＝雨强×径流系数×汇水面积÷3.6，单位为m³/s；地表暂存量＝max(Q−排水能力, 0)×降雨秒数。硬化、混合、较多绿地的系数分别取0.9、0.6、0.3。</p><p>未形成地表径流的雨量单独列出，不直接等同于地下水补给。模型忽略管网、地形、回水和蒸发等因素；暂存量不代表积水深度，参数不是南京实测值，不用于实际排水设计或防汛预测。</p><a class="source-link" href="https://www.usgs.gov/water-science-school/science/runoff-surface-and-overland-water-runoff" target="_blank" rel="noopener">USGS：地表径流</a></details>`}
 function resultsHTML(){const rows=values(),[hard,,green]=rows,delta=hard.stored-green.stored;return `<div class="lab-result-heading"><h2>地面类型对比</h2><span>${fmt(state.rain)} mm/h · ${fmt(state.duration)} 分钟 · ${fmt(state.area,1)} km²</span></div><div class="lab-result-cards">${rows.map(r=>{const percent=value=>r.total?value/r.total*100:0;return `<article class="lab-result-card ${r.cover}"><h3>${covers[r.cover].name}</h3><span class="lab-metric-label">地表暂存</span><strong class="lab-storage-value">${fmt(r.stored)}<small>m³</small></strong><div class="lab-balance-bar" role="img" aria-label="总降雨${fmt(r.total)}立方米，未形成径流${fmt(r.absorbed)}，排出${fmt(r.drainedVolume)}，暂存${fmt(r.stored)}"><i class="absorbed" style="width:${percent(r.absorbed)}%"></i><i class="drained" style="width:${percent(r.drainedVolume)}%"></i><i class="stored" style="width:${percent(r.stored)}%"></i></div><dl><div><dt>地表产流</dt><dd>${fmt(r.runoff,2)} m³/s</dd></div><div><dt>已排出</dt><dd>${fmt(r.drainedVolume)} m³</dd></div></dl></article>`}).join('')}</div><div class="lab-balance-legend"><span><i class="absorbed"></i>未形成径流</span><span><i class="drained"></i>已排出</span><span><i class="stored"></i>地表暂存</span></div><p class="lab-conclusion" role="status">${state.rain===0?'雨强为0，三个地面的地表产流和暂存量均为0。':delta>0?`相同参数下，较多绿地比硬化地面减少 ${fmt(hard.runoff-green.runoff,2)} m³/s 地表产流，地表暂存量减少 ${fmt(delta)} m³。`:'当前排水能力可排出三种地面的产流，地表暂存量均为0 m³。'}</p><div class="lab-total"><span>总降雨体积</span><strong>${fmt(hard.total)} m³</strong><span>降雨深度 ${fmt(state.rain*state.duration/60,1)} mm</span></div>`}
 function runsHTML(){return state.runs.length?`<div class="lab-record-scroll" tabindex="0" role="region" aria-label="已保存的参数对比表"><table class="lab-record-table" role="table"><caption class="sr-only">不同参数下三种地面的地表暂存量，单位m³</caption><thead><tr><th>参数组</th><th>雨强/历时</th><th>面积/排水</th><th>硬化</th><th>混合</th><th>绿地</th><th>操作</th></tr></thead><tbody>${state.runs.map((r,i)=>`<tr><th scope="row"><span class="lab-run-index">参数组 </span>${i+1}</th><td data-label="雨强 / 历时">${r.rain} mm/h<br>${r.duration} 分钟</td><td data-label="面积 / 排水">${fmt(r.area,1)} km²<br>${r.capacity} m³/s</td>${Object.keys(covers).map(cover=>`<td data-label="${covers[cover].name}暂存">${fmt(simulate({...r,cover}).stored)}<span class="lab-run-unit"> m³</span></td>`).join('')}<td class="lab-run-action"><button class="source-link" data-run-remove="${r.id}" aria-label="删除第${i+1}组参数">删除</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="lab-empty">尚未保存参数。保存后可对照雨强、历时、面积和排水能力。</p>'}
 function mapStage(){const point=window.HydroAtlas.places.find(p=>p.index===state.chosen)||window.HydroAtlas.places[0],profile=window.HydroSandbox.profiles[point.index];return `<div class="lab-map-layout"><section class="panel"><div class="lab-map-toolbar"><span>南京河湖</span><button class="btn" type="button" data-map-overview>全部地点</button></div><div id="journey-map" class="geographic-map" aria-label="南京河湖地点地图"></div><p class="geo-status" id="journey-map-status">正在载入水系…</p></section><aside class="lab-place-panel panel"><h2>河湖地点</h2><div class="lab-place-list" role="group" aria-label="选择地图地点">${window.HydroAtlas.places.map(p=>`<button id="journey-place-${p.index}" data-place="${p.index}" aria-pressed="${p.index===point.index}">${esc(p.name)}</button>`).join('')}</div><div class="lab-place-profile"><h3>${esc(point.name)}</h3><p>${{qinhuai:'秦淮河水系',yangtze:'长江南京段',lake:'湖泊'}[point.group]}</p><p>${esc(profile.fact)}</p><a class="source-link" href="${point.source}" target="_blank" rel="noopener">地点来源</a></div></aside></div>`}
 function observationStage(){const p=photo(),checks=state.checks[state.photo]||[];return `<div class="lab-observation"><figure class="observation-photo panel"><img src="${p.file}" alt="${esc(p.label)}的历史实景照片"><figcaption><strong>${esc(p.label)}</strong><small>${esc(p.date.slice(0,10))} · 历史照片</small><details class="image-credit photo-credit"><summary>图片信息</summary><div class="image-credit-body"><p>摄影：${esc(p.author)} · <a href="${p.source}" target="_blank" rel="noopener">原图</a> · <a href="${p.licenseUrl}" target="_blank" rel="noopener">${esc(p.license)}</a></p><p>${esc(p.displayChanges)}</p></div></details></figcaption></figure><section class="lab-observation-form panel"><h2>观察记录</h2><label for="observation-photo">照片</label><select id="observation-photo">${window.HydroAtlas.photos.map(item=>`<option value="${item.id}" ${state.photo===item.id?'selected':''}>${esc(item.label)}</option>`).join('')}</select><fieldset><legend>画面可见要素</legend>${Object.entries(featureNames).map(([id,label])=>`<label><input type="checkbox" data-observation-feature="${id}" ${checks.includes(id)?'checked':''}>${label}</label>`).join('')}</fieldset><label for="observation-note">补充记录</label><textarea id="observation-note" rows="5" maxlength="600" placeholder="记录可见的水面、岸线或植被情况。">${esc(state.note)}</textarea><button class="btn primary" data-finish>保存观察记录</button><p id="observation-save-status" role="status">${state.recorded?'已保存至当前浏览器。':''}</p><p class="lab-observation-note">历史照片仅用于观察，不能据此判断当前水情或水质。</p></section></div>`}
 function passport(){return `# 水文体验记录\n\n网页教学实验 · 非实测报告\n记录时间：${new Date().toISOString()}\n\n## 河湖地点\n${window.HydroAtlas.places.find(p=>p.index===state.chosen)?.name||'三汊河口'}\n\n## 当前实验\n雨强${state.rain}mm/h，历时${state.duration}分钟，面积${state.area}km²，排水能力${state.capacity}m³/s。\n${values().map(r=>`${covers[r.cover].name}：产流${fmt(r.runoff,2)}m³/s，排出${fmt(r.drainedVolume)}m³，地表暂存${fmt(r.stored)}m³。`).join('\n')}\n\n## 参数记录\n${state.runs.length?state.runs.map((r,i)=>`${i+1}. ${r.rain}mm/h，${r.duration}分钟，${r.area}km²，${r.capacity}m³/s；${Object.keys(covers).map(cover=>`${covers[cover].name}暂存${fmt(simulate({...r,cover}).stored)}m³`).join('，')}`).join('\n'):'未保存参数组。'}\n\n## 实景观察\n${window.HydroAtlas.photos.map(p=>`${p.label}（${p.date.slice(0,10)}）\n摄影：${p.author}；${p.license}\n原图：${p.source}\n许可：${p.licenseUrl}\n可见要素：${(state.checks[p.id]||[]).map(id=>featureNames[id]).join('、')||'未标记'}\n${state.notes[p.id]||'本次未填写文字观察。'}`).join('\n\n')}\n\n系数为教学设定，未形成地表径流的雨量不直接等同于地下水补给；暂存量不代表积水深度，不用于工程设计或防汛预测。\n`}
 function redraw(focusId){if(!controller)return;const id=focusId||document.activeElement?.id;mapController?.destroy();mapController=null;controller.root.innerHTML=render();bind(controller);if(id)controller.root.querySelector('#'+id)?.focus({preventScroll:true})}
 function choosePlace(index){if(!window.HydroAtlas.places.some(p=>p.index===index))return;state.chosen=index;state.found=true;save();redraw()}
 function saveRun(){state.trials=Object.keys(covers).map(cover=>({...input(state),cover}));const last=state.runs.at(-1);if(last&&Object.keys(input(state)).every(k=>last[k]===state[k])){controller?.toast('该组参数已保存。');return}state.runs.push({...input(state),id:Math.max(0,...state.runs.map(r=>r.id))+1});state.runs=state.runs.slice(-6);save();redraw();controller?.toast('已保存参数。')}
 function selectTab(step){if(![1,2,3].includes(step))return;state.step=step;save();redraw('journey-tab-'+step)}
 function bind(options){controller=options;const q=s=>options.root.querySelector(s),root=q('#journey');if(state.step===1){mapController=options.makeMap(q('#journey-map'),{stations:options.stations,selected:state.chosen,onSelect:choosePlace,statusElement:q('#journey-map-status'),focusAll:true,layers:{alerts:false}});if(state.found)mapController.focusStation?.(state.chosen,{openPopup:false})}
  root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-step'))selectTab(+b.dataset.step);else if(b.hasAttribute('data-map-overview')){state.found=false;mapController?.fitAll?.();save()}else if(b.hasAttribute('data-place'))choosePlace(+b.dataset.place);else if(b.hasAttribute('data-lab-rain')){state.rain=+b.dataset.labRain;state.trials=[];save();redraw()}else if(b.hasAttribute('data-save-run'))saveRun();else if(b.hasAttribute('data-reset-params')){Object.assign(state,input({}));state.trials=[];save();redraw()}else if(b.hasAttribute('data-run-remove')){state.runs=state.runs.filter(r=>r.id!==+b.dataset.runRemove);save();redraw('lab-save-run')}else if(b.hasAttribute('data-finish')){state.recorded=true;save();const status=q('#observation-save-status');if(status)status.textContent='已保存至当前浏览器。';options.toast('已保存观察记录。')}else if(b.hasAttribute('data-export')){save();options.download(passport(),'水文体验记录.md','text/markdown;charset=utf-8');options.toast('已导出体验记录。')}};
  root.onkeydown=e=>{const b=e.target.closest('[data-step]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=tabs.findIndex(([id])=>id===state.step),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next][0])};
  for(const name of ['rain','duration','area','capacity']){const control=q('#journey-'+name);if(control){control.oninput=()=>{state[name]=input({...state,[name]:control.value})[name];state.trials=[];q('#lab-'+name+'-output').textContent=fmt(state[name],name==='area'?1:0);q('#experiment-results').innerHTML=resultsHTML();const buttons=options.root.querySelectorAll?.('[data-lab-rain]')||[];buttons.forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.labRain===state.rain)))};control.onchange=save}}
  const select=q('#observation-photo');if(select)select.onchange=()=>{if(!photoIds.includes(select.value))return;state.notes[state.photo]=state.note;state.photo=select.value;state.note=state.notes[state.photo]||'';state.recorded=false;save();redraw('observation-photo')};
  const note=q('#observation-note');if(note)note.oninput=()=>{state.note=note.value.slice(0,600);state.notes[state.photo]=state.note;state.recorded=false;const status=q('#observation-save-status');if(status)status.textContent='';clearTimeout(saveTimer);saveTimer=setTimeout(save,250)};
  for(const check of options.root.querySelectorAll?.('[data-observation-feature]')||[])check.onchange=()=>{const selected=new Set(state.checks[state.photo]||[]);check.checked?selected.add(check.dataset.observationFeature):selected.delete(check.dataset.observationFeature);state.checks[state.photo]=[...selected];state.recorded=false;const status=q('#observation-save-status');if(status)status.textContent='';save()};
 }
 function destroy(){clearTimeout(saveTimer);if(controller)save();mapController?.destroy();mapController=null;controller=null}
 restore();window.HydroJourney={render,bind,destroy,simulate,comparison,covers,getState:()=>JSON.parse(JSON.stringify(state))};
})();
